// config.js: what the shared map-quiz engine (main.js, contract.js) needs
// to know about South America Quiz: the data (countries.js, generated by
// tools/build_map.py) and every text the engine shows. Static text (title,
// help, button labels before the script runs) is in index.html. Contract:
// shared/map-quiz/README.md.
import { MAP, COUNTRIES } from './countries.js';

const misclicks = (n) => (n ? ` · ${n} misclick${n === 1 ? '' : 's'}` : ' · no misclicks');
// A territory carries the state it belongs to: "French Guiana (France)".
const named = (c) => (c.of ? `${c.name} (${c.of})` : c.name);
const kind = COUNTRIES.some((c) => c.of) ? 'country or territory' : 'country';

export default {
  map: MAP,
  items: COUNTRIES,
  rounds: [
    {
      key: 'countries',
      label: 'Countries',
      prompt: 'Find',
      ask: named,
      miss: named,
      done: ({ total, misses }) => `All ${total} found${misclicks(misses)}. Now the capitals: find each one on the map.`,
    },
    {
      key: 'capitals',
      label: 'Capitals',
      prompt: `Find the ${kind} whose capital is`,
      ask: (c) => c.capital,
      miss: (c) => `${named(c)} · ${c.capital}`,
      done: ({ total, misses }) => `All ${total} capitals found${misclicks(misses)}. Countries again, in a new order.`,
    },
  ],
  text: {
    intro: {
      mouse: 'Find it on the map and click it. Zoom: mouse wheel or pinch. Move: drag or two-finger scroll.',
      touch: 'Find it on the map and tap it. Pinch to zoom, drag to move.',
    },
    newGame: 'New game: counters at zero, countries first.',
    reset: 'Reset the quiz',
    resetArmed: 'Really reset? Counters and colours are cleared',
    mapError: 'The map could not be loaded. Reload the page to try again.',
    theme: (other, override) => ({
      label: `Switch to ${other} theme`,
      title: override ? `Back to the system setting (${other})` : `Switch to the ${other} theme`,
    }),
  },
  // besideHud: without it, the landscape card sits over the Atlantic on
  // desktops, tablets and most phones, but on small phones (568x320) over
  // the tip of north-east Brazil; with it, no shape is ever under the HUD.
  view: { maxScale: 6, besideHud: true },
};
